import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { REQUEST_ERROR } from "../../errors/error-registry.js";
import { normalizeWorkflowApiBase, useStableWorkflowHeaders } from "./mutation-headers.js";
/** Default interval for auto-refreshing the workflow list */
const DEFAULT_REFRESH_INTERVAL_MS = 5_000;
/**
 * List and filter workflow runs.
 */
export function useWorkflowList(options = {}) {
    const { workflowId, status, createdAfter, createdBefore, pageSize = 20, apiBase = "/api/workflows", headers, credentials, autoRefresh = false, refreshInterval = DEFAULT_REFRESH_INTERVAL_MS, } = options;
    const normalizedApiBase = normalizeWorkflowApiBase(apiBase);
    const stableHeaders = useStableWorkflowHeaders(headers);
    const authorizationContext = useMemo(() => ({ credentials, normalizedApiBase, stableHeaders }), [credentials, normalizedApiBase, stableHeaders]);
    const currentAuthorizationContext = useRef(authorizationContext);
    currentAuthorizationContext.current = authorizationContext;
    const [runs, setRuns] = useState([]);
    const [totalCount, setTotalCount] = useState();
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [hasMore, setHasMore] = useState(false);
    const [cursor, setCursor] = useState();
    const [dataAuthorizationContext, setDataAuthorizationContext] = useState(authorizationContext);
    const requestSequence = useRef(0);
    const activeRequestSequence = useRef(null);
    const isCurrentRequest = useCallback((request) => request.sequence === requestSequence.current &&
        request.authorizationContext === currentAuthorizationContext.current, []);
    const [filter, setFilterState] = useState({
        workflowId,
        status,
        createdAfter,
        createdBefore,
        limit: pageSize,
    });
    const buildQueryString = useCallback((filterToUse, cursorToUse) => {
        const params = new URLSearchParams();
        if (filterToUse.workflowId)
            params.set("workflowId", filterToUse.workflowId);
        if (filterToUse.status) {
            const statuses = Array.isArray(filterToUse.status)
                ? filterToUse.status
                : [filterToUse.status];
            for (const s of statuses)
                params.append("status", s);
        }
        if (filterToUse.createdAfter) {
            params.set("createdAfter", filterToUse.createdAfter.toISOString());
        }
        if (filterToUse.createdBefore) {
            params.set("createdBefore", filterToUse.createdBefore.toISOString());
        }
        if (filterToUse.limit)
            params.set("limit", String(filterToUse.limit));
        if (cursorToUse)
            params.set("cursor", cursorToUse);
        return params.toString();
    }, []);
    const fetchRuns = useCallback(async (append = false) => {
        const sequence = ++requestSequence.current;
        const request = { authorizationContext, sequence };
        activeRequestSequence.current = sequence;
        try {
            const queryString = buildQueryString(filter, append ? cursor : undefined);
            const response = await fetch(`${normalizedApiBase}/runs?${queryString}`, {
                headers: stableHeaders,
                credentials,
            });
            if (!response.ok) {
                throw REQUEST_ERROR.create({
                    detail: `Failed to fetch runs: ${response.status}`,
                    status: response.status,
                });
            }
            const data = await response.json();
            const isBareArray = Array.isArray(data);
            const fetchedRuns = isBareArray ? data : data.runs ?? [];
            const nextCursor = isBareArray ? undefined : data.cursor;
            const total = isBareArray ? undefined : data.totalCount;
            if (!isCurrentRequest(request))
                return request;
            setDataAuthorizationContext(authorizationContext);
            setRuns((prev) => (append ? [...prev, ...fetchedRuns] : fetchedRuns));
            setCursor(nextCursor);
            setHasMore(Boolean(nextCursor));
            setTotalCount(total);
            setError(null);
        }
        catch (err) {
            if (!isCurrentRequest(request))
                return request;
            setError(err instanceof Error ? err : new Error(String(err)));
        }
        finally {
            if (activeRequestSequence.current === sequence) {
                activeRequestSequence.current = null;
            }
        }
        return request;
    }, [
        authorizationContext,
        buildQueryString,
        credentials,
        cursor,
        filter,
        isCurrentRequest,
        normalizedApiBase,
        stableHeaders,
    ]);
    useEffect(() => {
        // Data from one authorization context must not remain visible while a
        // replacement request is pending or after it fails.
        requestSequence.current++;
        activeRequestSequence.current = null;
        setRuns([]);
        setCursor(undefined);
        setHasMore(false);
        setTotalCount(undefined);
        setError(null);
        return () => {
            // Pending fetches and body reads must not update state after unmount.
            requestSequence.current++;
            activeRequestSequence.current = null;
        };
    }, [authorizationContext]);
    useEffect(() => {
        let cancelled = false;
        async function doFetch() {
            setIsLoading(true);
            const request = await fetchRuns(false);
            if (!cancelled && isCurrentRequest(request))
                setIsLoading(false);
        }
        void doFetch();
        return () => {
            cancelled = true;
        };
    }, [fetchRuns, filter, isCurrentRequest]);
    useEffect(() => {
        if (!autoRefresh)
            return;
        const intervalId = setInterval(() => {
            if (activeRequestSequence.current !== null)
                return;
            fetchRuns(false);
        }, refreshInterval);
        return () => clearInterval(intervalId);
    }, [autoRefresh, fetchRuns, refreshInterval]);
    const loadMore = useCallback(async () => {
        if (!hasMore || isLoading)
            return;
        setIsLoading(true);
        const request = await fetchRuns(true);
        if (isCurrentRequest(request))
            setIsLoading(false);
    }, [fetchRuns, hasMore, isCurrentRequest, isLoading]);
    const refresh = useCallback(async () => {
        setCursor(undefined);
        setIsLoading(true);
        const request = await fetchRuns(false);
        if (isCurrentRequest(request))
            setIsLoading(false);
    }, [fetchRuns, isCurrentRequest]);
    const setFilter = useCallback((newFilter) => {
        setCursor(undefined);
        setFilterState((prev) => ({
            ...prev,
            workflowId: newFilter.workflowId ?? prev.workflowId,
            status: newFilter.status ?? prev.status,
            createdAfter: newFilter.createdAfter ?? prev.createdAfter,
            createdBefore: newFilter.createdBefore ?? prev.createdBefore,
            limit: newFilter.pageSize ?? prev.limit,
        }));
    }, []);
    const hasCurrentAuthorizationData = dataAuthorizationContext === authorizationContext;
    return {
        runs: hasCurrentAuthorizationData ? runs : [],
        totalCount: hasCurrentAuthorizationData ? totalCount : undefined,
        isLoading,
        error,
        hasMore: hasCurrentAuthorizationData ? hasMore : false,
        loadMore,
        refresh,
        setFilter,
        filter,
    };
}
